create table if not exists users(id text primary key, email text not null unique, email_salt text not null, plan text not null default 'free', retention_days int not null default 365, created_at timestamptz not null default now());
create table if not exists messages(id text primary key, user_id text not null references users(id) on delete cascade, subject_encrypted text, mode text not null check (mode in ('combined','per_recipient')), sent_at timestamptz not null default now(), created_at timestamptz not null default now());
create table if not exists recipients(id text primary key, message_id text not null references messages(id) on delete cascade, email_hash text, display_label_encrypted text, created_at timestamptz not null default now());
create table if not exists events(id text primary key, recipient_id text not null references recipients(id) on delete cascade, occurred_at timestamptz not null, classification text not null check (classification in ('REAL_OPEN','POSSIBLY_OPENED','SELF_OPEN')), reason text not null, ua_family text, country text, suspected_bot boolean not null default false, created_at timestamptz not null default now());
create table if not exists optouts(recipient_id text primary key, created_at timestamptz not null default now());
create table if not exists rules_versions(version int primary key, rules jsonb not null, created_at timestamptz not null default now());
create index on messages(user_id, created_at); create index on recipients(message_id); create index on events(recipient_id, occurred_at);
-- Token is derived (HMAC of recipients.id), so no token column. No raw IP column by design; events older than users.retention_days are purged.
